using System.Windows;using LabMaster.Services;namespace LabMaster;public partial class QCHistoryWindow:Window{readonly QCService service=new();readonly int qcId;readonly string material;public QCHistoryWindow(int id,string name){InitializeComponent();qcId=id;material=name;TitleText.Text=$"QC Result History — {name}";Loaded+=async(_,_)=>await LoadAsync();}async Task LoadAsync(){try{Grid.ItemsSource=await service.GetResultsAsync(qcId);}catch(Exception ex){MessageBox.Show(ex.Message,"Lab Master",MessageBoxButton.OK,MessageBoxImage.Error);}}}